/**
 * Huawei Cloud SDK-HMAC-SHA256 signing + RFC 9449 DPoP (ES256).
 *
 * Ported from our Rust signer (`codearts/signer.rs`, itself verified against
 * `signer_vectors.json` generated by the MIT `Coding2API` Go signer) and
 * `codearts/dpop.rs`.
 *
 * Three details that silently produce 401 when wrong:
 *   1. `canonicalURI` is rebuilt segment-by-segment from the **percent-decoded**
 *      path and always gets a trailing `/` — `/api/v2/chat/completions` signs as
 *      `/api/v2/chat/completions/`.
 *   2. The unreserved set is JS `encodeURIComponent`'s, i.e. `-_.!~*'()` stay
 *      literal. `!'()` are NOT RFC 3986 unreserved; do not use encodeURIComponent
 *      blindly (it leaves them alone, which happens to be right) nor a strict
 *      RFC 3986 encoder (which escapes them, which is wrong).
 *   3. Every outgoing header participates in the signature — `X-Sdk-Date`,
 *      `X-Security-Token`, `X-Domain-Id`, `maas_type` — except `Authorization`
 *      itself. Missing `maas_type` on a benefit model is answered with
 *      `InferHub.002002009.404` ("model is not registered"), which reads like a
 *      catalog problem but is really a signature/header problem.
 */
import crypto from "node:crypto";

const SIGNING_ALGORITHM = "SDK-HMAC-SHA256";
const HEADER_XSDK_DATE = "X-Sdk-Date";
const HEADER_AUTHORIZATION = "Authorization";
const HEADER_CONTENT_SHA256 = "X-Sdk-Content-Sha256";
const HEADER_SECURITY_TOKEN = "X-Security-Token";
const HEADER_DOMAIN_ID = "X-Domain-Id";
const EMPTY_BODY_SHA256 = "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855";

/** P-256 group order (SEC 2 / FIPS 186-4). */
const P256_ORDER = BigInt("0xFFFFFFFF00000000FFFFFFFFFFFFFFFFBCE6FAADA7179E84F3B9CAC2FC632551");
const P256_HALF_ORDER = P256_ORDER / 2n;

function sha256Hex(bytes) {
  return crypto.createHash("sha256").update(bytes).digest("hex");
}

function hmacSha256Hex(key, message) {
  return crypto.createHmac("sha256", key).update(message, "utf8").digest("hex");
}

function unhex(byte) {
  if (byte >= 0x30 && byte <= 0x39) return byte - 0x30;
  if (byte >= 0x61 && byte <= 0x66) return byte - 0x61 + 10;
  if (byte >= 0x41 && byte <= 0x46) return byte - 0x41 + 10;
  return -1;
}

/**
 * Go `net/url` unescape semantics. `plusIsSpace` is true for query components.
 * Returns null on a malformed escape (caller drops that pair, like Go's
 * `ParseQuery` dropping one key/value instead of failing the request).
 */
function unescapeBytes(input, plusIsSpace) {
  const bytes = Buffer.isBuffer(input) ? input : Buffer.from(String(input), "utf8");
  const out = [];
  for (let index = 0; index < bytes.length; index += 1) {
    const byte = bytes[index];
    if (byte === 0x25) {
      if (index + 2 >= bytes.length) return null;
      const high = unhex(bytes[index + 1]);
      const low = unhex(bytes[index + 2]);
      if (high < 0 || low < 0) return null;
      out.push((high << 4) | low);
      index += 2;
      continue;
    }
    if (plusIsSpace && byte === 0x2b) {
      out.push(0x20);
      continue;
    }
    out.push(byte);
  }
  return Buffer.from(out);
}

function isUnreserved(byte) {
  return (
    (byte >= 0x41 && byte <= 0x5a) ||
    (byte >= 0x61 && byte <= 0x7a) ||
    (byte >= 0x30 && byte <= 0x39) ||
    byte === 0x2d || // -
    byte === 0x5f || // _
    byte === 0x2e || // .
    byte === 0x21 || // !
    byte === 0x7e || // ~
    byte === 0x2a || // *
    byte === 0x27 || // '
    byte === 0x28 || // (
    byte === 0x29 // )
  );
}

/** JS `encodeURIComponent` percent-encoding over raw bytes (uppercase hex). */
export function encodeComponent(input) {
  const bytes = Buffer.isBuffer(input) ? input : Buffer.from(String(input), "utf8");
  let out = "";
  for (const byte of bytes) {
    if (isUnreserved(byte)) out += String.fromCharCode(byte);
    else out += `%${byte.toString(16).toUpperCase().padStart(2, "0")}`;
  }
  return out;
}

function parseUrl(rawUrl) {
  const schemeAt = rawUrl.indexOf("://");
  if (schemeAt < 0) throw new Error("CodeArts 上游地址缺少 scheme");
  const rest = rawUrl.slice(schemeAt + 3);
  const authorityEnd = rest.search(/[/?#]/);
  const authority = authorityEnd < 0 ? rest : rest.slice(0, authorityEnd);
  if (!authority) throw new Error("CodeArts 上游地址缺少主机名");
  const tail = authorityEnd < 0 ? "" : rest.slice(authorityEnd);
  const beforeFragment = tail.split("#")[0];
  const queryAt = beforeFragment.indexOf("?");
  const rawPath = queryAt < 0 ? beforeFragment : beforeFragment.slice(0, queryAt);
  const rawQuery = queryAt < 0 ? "" : beforeFragment.slice(queryAt + 1);
  const path = unescapeBytes(rawPath, false);
  if (path === null) throw new Error(`CodeArts 上游地址路径转义非法：${rawPath}`);
  return { authority, path, rawQuery };
}

/** Canonical URI: encode each decoded segment, always end with `/`. */
export function canonicalUri(pathInput) {
  const path = Buffer.isBuffer(pathInput) ? pathInput : Buffer.from(String(pathInput), "utf8");
  if (path.length === 0) return "/";
  const segments = [];
  let start = 0;
  for (let index = 0; index <= path.length; index += 1) {
    if (index === path.length || path[index] === 0x2f) {
      segments.push(encodeComponent(path.subarray(start, index)));
      start = index + 1;
    }
  }
  let escaped = segments.join("/");
  if (!escaped.endsWith("/")) escaped += "/";
  return escaped;
}

function queryPairs(rawQuery) {
  const pairs = [];
  for (const part of String(rawQuery || "").split("&")) {
    if (!part || part.includes(";")) continue;
    const eq = part.indexOf("=");
    const rawKey = eq < 0 ? part : part.slice(0, eq);
    const rawValue = eq < 0 ? "" : part.slice(eq + 1);
    const key = unescapeBytes(rawKey, true);
    const value = unescapeBytes(rawValue, true);
    if (key === null || value === null) continue;
    pairs.push([key, value]);
  }
  return pairs;
}

/** Sort by encoded key then raw value; encode key and value with the same set. */
export function canonicalQueryString(rawQuery) {
  const pairs = queryPairs(rawQuery);
  pairs.sort((a, b) => {
    const keyA = encodeComponent(a[0]);
    const keyB = encodeComponent(b[0]);
    if (keyA !== keyB) return keyA < keyB ? -1 : 1;
    return Buffer.compare(a[1], b[1]);
  });
  return pairs.map(([key, value]) => `${encodeComponent(key)}=${encodeComponent(value)}`).join("&");
}

/** SDK date: `YYYYMMDDTHHMMSSZ` in UTC. */
export function sdkDateNow(nowMs = Date.now()) {
  const date = new Date(nowMs);
  const pad = (n) => String(n).padStart(2, "0");
  return (
    `${date.getUTCFullYear()}${pad(date.getUTCMonth() + 1)}${pad(date.getUTCDate())}` +
    `T${pad(date.getUTCHours())}${pad(date.getUTCMinutes())}${pad(date.getUTCSeconds())}Z`
  );
}

/**
 * Header bag with case-insensitive overwrite that keeps insertion position,
 * mirroring Rust's `Headers` (deterministic, unlike Go's map iteration).
 */
function makeHeaderBag(input) {
  const entries = [];
  const set = (name, value) => {
    const lower = String(name).toLowerCase();
    const index = entries.findIndex(([existing]) => existing.toLowerCase() === lower);
    if (index >= 0) entries[index] = [entries[index][0], String(value)];
    else entries.push([String(name), String(value)]);
  };
  for (const [name, value] of Object.entries(input || {})) {
    if (value === undefined || value === null) continue;
    set(name, value);
  }
  return { entries, set, has: (name) => entries.some(([existing]) => existing.toLowerCase() === String(name).toLowerCase()), get: (name) => entries.find(([existing]) => existing.toLowerCase() === String(name).toLowerCase())?.[1] };
}

/**
 * Sign a request.
 *
 * @param {object} params
 * @param {string} params.method
 * @param {string} params.url
 * @param {Record<string,string>} params.headers  outgoing headers, WITHOUT Authorization
 * @param {string|Buffer} [params.body]
 * @param {{accessKeyId:string, secretAccessKey:string, securityToken?:string, domainId?:string}} params.credential
 * @param {boolean} [params.includeHost]
 * @param {string} [params.date] override X-Sdk-Date (tests)
 * @returns {{headers: Record<string,string>, canonicalRequest:string, stringToSign:string, signedHeaders:string, signature:string}}
 */
export function signCodeArtsRequest({ method, url, headers = {}, body = "", credential, includeHost = false, date }) {
  if (!credential?.accessKeyId || !credential?.secretAccessKey) {
    throw new Error("CodeArts 凭据不完整：access key 与 secret key 都得有");
  }
  const parsed = parseUrl(url);
  const bag = makeHeaderBag(headers);
  if (credential.securityToken) bag.set(HEADER_SECURITY_TOKEN, credential.securityToken);
  if (credential.domainId) bag.set(HEADER_DOMAIN_ID, credential.domainId);
  if (!bag.has(HEADER_XSDK_DATE)) bag.set(HEADER_XSDK_DATE, date || sdkDateNow());
  if (includeHost && !bag.has("host")) bag.set("Host", parsed.authority);
  const sdkDate = bag.get(HEADER_XSDK_DATE) || "";

  // Canonical headers: lower-case name, trimmed value, sorted by name.
  const canonical = bag.entries
    .map(([name, value]) => [name.toLowerCase(), String(value).trim()])
    .sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
  const canonicalHeaders = canonical.map(([name, value]) => `${name}:${value}\n`).join("");
  const signedHeaders = canonical.map(([name]) => name).join(";");

  const bodyBytes = Buffer.isBuffer(body) ? body : Buffer.from(String(body || ""), "utf8");
  const override = canonical.find(([name]) => name === HEADER_CONTENT_SHA256.toLowerCase())?.[1];
  const methodUpper = String(method || "GET").toUpperCase();
  const carriesBody = methodUpper === "PUT" || methodUpper === "PATCH" || methodUpper === "POST";
  const payloadHash = override || (carriesBody ? sha256Hex(bodyBytes) : EMPTY_BODY_SHA256);

  const canonicalRequest = [
    method,
    canonicalUri(parsed.path),
    canonicalQueryString(parsed.rawQuery),
    canonicalHeaders,
    signedHeaders,
    payloadHash,
  ].join("\n");
  const stringToSign = [SIGNING_ALGORITHM, sdkDate, sha256Hex(Buffer.from(canonicalRequest, "utf8"))].join("\n");
  const signature = hmacSha256Hex(credential.secretAccessKey, stringToSign);

  bag.set(
    HEADER_AUTHORIZATION,
    `${SIGNING_ALGORITHM} Access=${credential.accessKeyId}, SignedHeaders=${signedHeaders}, Signature=${signature}`
  );

  const out = {};
  for (const [name, value] of bag.entries) out[name] = value;
  return { headers: out, canonicalRequest, stringToSign, signedHeaders, signature };
}

function base64Url(buffer) {
  return Buffer.from(buffer).toString("base64").replace(/=+$/, "").replace(/\+/g, "-").replace(/\//g, "_");
}

/**
 * ECDSA low-S normalisation (BIP 62 / RFC 6979 §2.4 shape).
 *
 * Node's `crypto.sign` with `dsaEncoding: "ieee-p1363"` returns `R || S` (32+32
 * bytes) and does NOT normalise S — our own soak produced ~50% high-S halves.
 * Huawei's STS verifier rejects those non-deterministically, so every proof goes
 * through this before base64url encoding. `R` is untouched.
 *
 * @param {Buffer} rawSignature 64-byte IEEE P1363 signature
 * @returns {Buffer} 64-byte signature with `S <= n/2`
 */
export function normalizeLowS(rawSignature) {
  const signature = Buffer.from(rawSignature);
  if (signature.length !== 64) throw new Error("ES256 签名必须是 64 字节（R||S）");
  const r = signature.subarray(0, 32);
  const s = BigInt(`0x${signature.subarray(32, 64).toString("hex")}`);
  if (s <= P256_HALF_ORDER) return signature;
  const flipped = (P256_ORDER - s).toString(16).padStart(64, "0");
  return Buffer.concat([r, Buffer.from(flipped, "hex")]);
}

/**
 * Build a DPoP proof JWS for the STS token endpoint.
 *
 * @param {object} params
 * @param {crypto.KeyObject} params.privateKey P-256 private key
 * @param {{kty:"EC",crv:"P-256",x:string,y:string}} params.publicJwk
 * @param {string} params.method
 * @param {string} params.url  `htu` (no query/fragment)
 * @param {number} [params.iat] seconds since epoch
 * @param {string} [params.jti] 32-byte nonce, base64url
 * @param {string} [params.nonce] STS nonce when the server requires one
 */
export function buildDpopProof({ privateKey, publicJwk, method, url, iat, jti, nonce }) {
  if (!privateKey || !publicJwk?.x || !publicJwk?.y) throw new Error("DPoP 需要完整的 P-256 密钥对");
  const header = {
    typ: "dpop+jwt",
    alg: "ES256",
    jwk: { kty: "EC", crv: "P-256", x: publicJwk.x, y: publicJwk.y },
  };
  const payload = {
    htu: String(url).split("?")[0].split("#")[0],
    htm: String(method || "POST").toUpperCase(),
    iat: iat ?? Math.floor(Date.now() / 1000),
    jti: jti || base64Url(crypto.randomBytes(16)),
  };
  if (nonce) payload.nonce = nonce;
  const signingInput = `${base64Url(Buffer.from(JSON.stringify(header)))}.${base64Url(Buffer.from(JSON.stringify(payload)))}`;
  const raw = crypto.sign("sha256", Buffer.from(signingInput), { key: privateKey, dsaEncoding: "ieee-p1363" });
  // Low-S is mandatory here, not cosmetic: see normalizeLowS.
  return `${signingInput}.${base64Url(normalizeLowS(raw))}`;
}

/** Convenience: ES256 JWK pair from a PEM private key (used by the OAuth TODO). */
export function dpopKeyFromPrivateKey(privateKey) {
  const publicKey = crypto.createPublicKey(privateKey);
  const jwk = publicKey.export({ format: "jwk" });
  return { privateKey, publicJwk: { kty: "EC", crv: "P-256", x: jwk.x, y: jwk.y } };
}
